import React, { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { Search } from "lucide-react";
import SiteNav from "@/components/SiteNav";
import SiteFooter from "@/components/SiteFooter";
import { useIsMobile } from "@/hooks/use-media-query";
import {
  PAGE, SURFACE, SURFACE_2, BORDER, BORDER_SUBTLE, TEXT, MUTED, SUBTLE,
  GOLD, GREEN, BLURPLE, PLATINUM, ORANGE, RADIUS, LAYOUT, FONT_MONO, alpha,
} from "@/theme";
// Both generated by the bot repo's features/build.js --public; edit the bot
// repo's features/ folder, not these.
import data from "@/data/features.json";
import "@/styles/feature-scenes.css";

type Status = "stable" | "beta" | "planned";

interface FeatureCommand {
  name: string; kind: string; description: string; permissions: string[];
  aliases: string[]; copy: string;
  options: { name: string; type: string; description: string; required: boolean; choices: string[] }[];
}
interface Feature {
  id: string; name: string; status: Status; building: boolean; sinceLabel: string;
  summary: string; lead: string; points: string[]; use: string[]; rules: string[];
  why: { title: string; text: string }[]; arrived: { label: string; what: string }[];
  related: string[]; commands: FeatureCommand[]; scene: string;
}

const FEATURES = data.features as Feature[];
const BY_ID = Object.fromEntries(FEATURES.map((f) => [f.id, f]));
const STATUS_TEXT = data.statuses as Record<Status, string>;
const ROWS: { status: Status; title: string }[] = [
  { status: "stable", title: "Stable" },
  { status: "beta", title: "Beta" },
  { status: "planned", title: "Planned" },
];
const CHIP: Record<Status, { label: string; color: string }> = {
  stable: { label: "Stable", color: GREEN },
  beta: { label: "Beta", color: BLURPLE },
  planned: { label: "Planned", color: PLATINUM },
};
const SCENE_W = 760;
const SCENE_H = 475;

/** `code` in the copy becomes <code>, everything else stays text. */
function Inline({ text }: { text: string }) {
  return (
    <>
      {text.split(/(`[^`]+`)/).map((part, i) =>
        part.startsWith("`") && part.endsWith("`") ? (
          <code key={i} style={{ fontFamily: FONT_MONO, fontSize: "0.88em", background: SURFACE_2, border: `1px solid ${BORDER_SUBTLE}`, borderRadius: RADIUS.sm, padding: "1px 5px" }}>
            {part.slice(1, -1)}
          </code>
        ) : (
          <React.Fragment key={i}>{part}</React.Fragment>
        ),
      )}
    </>
  );
}

function Chip({ status, building }: { status: Status; building?: boolean }) {
  const c = CHIP[status];
  return (
    <>
      <span style={{ background: alpha(c.color, 0.12), color: c.color, borderRadius: RADIUS.pill, padding: "2px 10px", fontSize: 12, fontWeight: 600 }}>{c.label}</span>
      {building && <span style={{ background: alpha(ORANGE, 0.12), color: ORANGE, borderRadius: RADIUS.pill, padding: "2px 10px", fontSize: 12, fontWeight: 600 }}>Being built</span>}
    </>
  );
}

/**
 * A feature's scene, scaled to the box it sits in. The scene markup is the
 * bot repo's own static HTML (features/boards/*.html; its build refuses
 * scripts and event attributes), not anything a visitor typed.
 */
function Scene({ html, width }: { html: string; width?: number }) {
  const box = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(width ? width / SCENE_W : 1);
  useLayoutEffect(() => {
    if (width || !box.current) return;
    const measure = () => setScale((box.current?.clientWidth ?? SCENE_W) / SCENE_W);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(box.current);
    return () => observer.disconnect();
  }, [width]);
  return (
    <div ref={box} aria-hidden="true" style={{ width: width ?? "100%", height: SCENE_H * scale, overflow: "hidden", pointerEvents: "none", flex: "none" }}>
      <div style={{ transform: `scale(${scale})`, transformOrigin: "0 0" }} dangerouslySetInnerHTML={{ __html: html }} />
    </div>
  );
}

function Card({ f }: { f: Feature }) {
  const planned = f.status === "planned";
  return (
    <li style={{ listStyle: "none" }}>
      <a
        href={`#${f.id}`}
        className="link-quiet"
        style={{
          display: "flex", flexDirection: "column", height: "100%", textDecoration: "none", color: TEXT,
          background: SURFACE, border: `1px ${planned ? "dashed" : "solid"} ${BORDER}`, borderRadius: RADIUS.lg, overflow: "hidden",
        }}
      >
        {f.scene && <Scene html={f.scene} width={264} />}
        <span style={{ padding: "12px 14px", display: "flex", flexDirection: "column", gap: 4, flex: 1 }}>
          <span style={{ fontWeight: 700, fontSize: 15 }}>{f.name}</span>
          <span style={{ color: MUTED, fontSize: 13, flex: 1 }}>{f.summary}</span>
          <span style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap", marginTop: 6 }}>
            <Chip status={f.status} building={f.building} />
            {f.sinceLabel && <span style={{ color: SUBTLE, fontSize: 12 }}>since {f.sinceLabel}</span>}
          </span>
        </span>
      </a>
    </li>
  );
}

function CommandBlock({ c }: { c: FeatureCommand }) {
  const [copied, setCopied] = useState(false);
  const kind = c.kind === "prefix" ? "PREFIX" : c.kind === "slash" ? "SLASH" : c.kind === "user-context" ? "USER MENU" : "MESSAGE MENU";
  const copy = async () => {
    try { await navigator.clipboard.writeText(c.copy); } catch { /* the button still says what it would copy */ }
    setCopied(true);
    setTimeout(() => setCopied(false), 1200);
  };
  return (
    <div style={{ border: `1px solid ${BORDER}`, borderRadius: RADIUS.md, overflow: "hidden", marginBottom: 10 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap", padding: "9px 14px", background: SURFACE }}>
        <code style={{ fontFamily: FONT_MONO, fontSize: 14, color: TEXT }}>{c.name}</code>
        <span style={{ border: `1px solid ${alpha(BLURPLE, 0.5)}`, color: BLURPLE, borderRadius: RADIUS.sm, padding: "0 7px", fontSize: 11, fontWeight: 600 }}>{kind}</span>
        {c.permissions.length > 0 && <span style={{ color: SUBTLE, fontSize: 12 }}>needs {c.permissions.join(", ")}</span>}
        <span style={{ flex: 1 }} />
        <button type="button" className="sx-btn sx-btn--ghost" onClick={copy} aria-label={`Copy ${c.copy}`} style={{ height: 30, padding: "0 12px", fontSize: 13 }}>
          {copied ? "Copied" : "Copy"}
        </button>
      </div>
      {c.description && <div style={{ padding: "8px 14px 0", color: MUTED, fontSize: 14 }}>{c.description}</div>}
      {c.aliases.length > 0 && <div style={{ padding: "6px 14px 0", color: SUBTLE, fontSize: 13 }}>Also: {c.aliases.map((a) => `taxx!${a}`).join(", ")}</div>}
      {c.options.length > 0 && (
        <div style={{ display: "grid", gridTemplateColumns: "minmax(90px, 140px) 70px minmax(0, 1fr)", gap: "6px 12px", padding: "10px 14px", marginTop: 8, borderTop: `1px solid ${BORDER_SUBTLE}`, fontSize: 13 }}>
          {c.options.map((o) => (
            <React.Fragment key={o.name}>
              <code style={{ fontFamily: FONT_MONO, overflowWrap: "anywhere" }}>{o.name}</code>
              <span style={{ color: o.required ? ORANGE : SUBTLE }}>{o.required ? "required" : "optional"}</span>
              <span style={{ color: MUTED }}>{o.description}{o.choices.length > 0 && <span style={{ color: SUBTLE }}> ({o.choices.join(", ")})</span>}</span>
            </React.Fragment>
          ))}
        </div>
      )}
      {!c.options.length && <div style={{ height: 10 }} />}
    </div>
  );
}

function FeatureView({ f, isMobile }: { f: Feature; isMobile: boolean }) {
  const planned = f.status === "planned";
  const h2: React.CSSProperties = { fontSize: 19, fontWeight: 700, margin: "24px 0 8px", color: TEXT };
  return (
    <article>
      <div style={{ display: "flex", alignItems: "center", gap: 8, margin: "0 0 14px", flexWrap: "wrap" }}>
        <a href="#" className="link-quiet" style={{ color: MUTED, textDecoration: "none" }}>← All features</a>
        <span style={{ flex: 1 }} />
        <Chip status={f.status} building={f.building} />
        {f.sinceLabel && <span style={{ color: SUBTLE, fontSize: 13 }}>since {f.sinceLabel}</span>}
      </div>
      <div style={{ display: "flex", flexDirection: isMobile ? "column" : "row", border: `1px solid ${BORDER}`, borderRadius: RADIUS.xl, overflow: "hidden", background: SURFACE }}>
        <div style={{ width: isMobile ? "100%" : 600, flex: "none", background: planned ? SURFACE_2 : "#313338" }}>
          {f.scene ? <Scene html={f.scene} /> : (
            <div style={{ aspectRatio: "16 / 10", display: "flex", alignItems: "center", justifyContent: "center", color: SUBTLE }}>Planned: no picture until it's built</div>
          )}
        </div>
        <div style={{ padding: "22px 26px", display: "flex", flexDirection: "column", gap: 8 }}>
          <div style={{ fontSize: 12, letterSpacing: "0.12em", fontWeight: 700, color: SUBTLE }}>{planned ? "PLANNED FEATURE" : "FEATURE"}</div>
          <h1 style={{ margin: 0, fontSize: 30, fontWeight: 800, letterSpacing: "-0.02em" }}>{f.name}</h1>
          <div style={{ fontSize: 12, letterSpacing: "0.12em", fontWeight: 700, color: GOLD, marginTop: 6 }}>{planned ? "WHAT IT WOULD DO" : "WHAT IT DOES"}</div>
          <ol style={{ margin: 0, paddingLeft: 20, listStyle: "decimal", display: "flex", flexDirection: "column", gap: 6, color: MUTED }}>
            {f.points.map((p) => <li key={p}><Inline text={p} /></li>)}
          </ol>
        </div>
      </div>
      <p style={{ color: MUTED, fontSize: 16, maxWidth: 820, margin: "18px 0 0" }}><Inline text={f.lead} /></p>
      <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "minmax(0, 1.35fr) minmax(0, 1fr)", gap: isMobile ? 0 : 36 }}>
        <div>
          {f.use.length > 0 && (<><h2 style={h2}>How to use it</h2><ul style={{ paddingLeft: 20, margin: 0, listStyle: "disc", display: "flex", flexDirection: "column", gap: 6, color: MUTED }}>{f.use.map((u) => <li key={u}><Inline text={u} /></li>)}</ul></>)}
          {f.rules.length > 0 && (<><h2 style={h2}>How it behaves</h2><ul style={{ paddingLeft: 20, margin: 0, listStyle: "disc", display: "flex", flexDirection: "column", gap: 6, color: MUTED }}>{f.rules.map((r) => <li key={r}><Inline text={r} /></li>)}</ul></>)}
          {f.commands.length > 0 && (<><h2 style={h2}>Commands</h2>{f.commands.map((c) => <CommandBlock key={c.name} c={c} />)}</>)}
        </div>
        <div>
          {f.why.length > 0 && (<><h2 style={h2}>Why it works this way</h2>{f.why.map((w) => <p key={w.title} style={{ color: MUTED, margin: "0 0 10px" }}><b style={{ color: TEXT }}>{w.title}.</b> <Inline text={w.text} /></p>)}</>)}
          {f.arrived.length > 0 && (<><h2 style={h2}>Arrived</h2>{f.arrived.map((a) => (
            <div key={a.what} style={{ display: "flex", gap: 12, color: MUTED, marginBottom: 6 }}><span style={{ color: BLURPLE, fontWeight: 600, width: 100, flex: "none" }}>{a.label}</span><span><Inline text={a.what} /></span></div>
          ))}</>)}
          {f.related.length > 0 && (<><h2 style={h2}>Related</h2><div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>{f.related.map((r) => (
            <a key={r} href={`#${r}`} className="link-quiet" style={{ border: `1px solid ${BORDER}`, borderRadius: RADIUS.pill, padding: "4px 12px", color: GOLD, textDecoration: "none" }}>{BY_ID[r]?.name ?? r}</a>
          ))}</div></>)}
        </div>
      </div>
      {planned && <p style={{ color: SUBTLE, marginTop: 24 }}>Plans can change, and there is no date.</p>}
    </article>
  );
}

/** The open feature lives in the URL hash, so a feature can be linked and Back works. */
function useHashFeature(): Feature | null {
  const read = () => BY_ID[decodeURIComponent(window.location.hash.slice(1))] ?? null;
  const [feature, setFeature] = useState<Feature | null>(read);
  useEffect(() => {
    const onHash = () => { setFeature(read()); window.scrollTo(0, 0); };
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  }, []);
  return feature;
}

export default function Features() {
  const isMobile = useIsMobile();
  const open = useHashFeature();
  const [query, setQuery] = useState("");
  const gutter = isMobile ? LAYOUT.gutterMobile : LAYOUT.gutter;

  const rows = useMemo(() => {
    const q = query.trim().toLowerCase();
    return ROWS.map((r) => ({
      ...r,
      items: FEATURES.filter((f) => f.status === r.status && (!q
        || [f.name, f.summary, ...f.commands.map((c) => c.name)].join(" ").toLowerCase().includes(q))),
    }));
  }, [query]);
  const shown = rows.reduce((n, r) => n + r.items.length, 0);

  return (
    <div style={PAGE}>
      <a className="skip-link" href="#main">Skip to content</a>
      <SiteNav current="features" />
      <main id="main" style={{ maxWidth: LAYOUT.maxWidth, margin: "0 auto", padding: `${isMobile ? 40 : 64}px ${gutter}px 48px` }}>
        {open ? <FeatureView f={open} isMobile={isMobile} /> : (
          <>
            <div style={{ fontSize: 12, fontWeight: 700, letterSpacing: "0.12em", color: GOLD }}>FEATURES</div>
            <h1 style={{ margin: "10px 0 8px", fontSize: isMobile ? 34 : 46, fontWeight: 800, letterSpacing: "-0.02em" }}>Everything syntaxx does</h1>
            <p style={{ color: MUTED, fontSize: 16, maxWidth: 700, margin: "0 0 18px" }}>
              Each feature shown the way it looks in your server. New ones are tried in Beta first.
            </p>
            <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
              <div style={{ position: "relative", width: 340, maxWidth: "100%" }}>
                <Search size={16} color={SUBTLE} aria-hidden="true" style={{ position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)", pointerEvents: "none" }} />
                <label htmlFor="feature-search" className="sr-only">Find a feature</label>
                <input
                  id="feature-search" type="search" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Find a feature"
                  style={{ width: "100%", boxSizing: "border-box", height: 42, background: SURFACE, border: `1px solid ${BORDER}`, borderRadius: RADIUS.md, padding: "0 16px 0 40px", color: TEXT, fontSize: 14, fontFamily: "inherit", outline: "none" }}
                />
              </div>
              <span style={{ color: SUBTLE, fontSize: 13 }}>Looking for a command? <a href="/commands" style={{ color: GOLD }}>All commands</a></span>
            </div>
            <p aria-live="polite" className="sr-only">{shown} feature{shown === 1 ? "" : "s"} shown</p>

            {rows.map((r) => (
              <section key={r.status} aria-labelledby={`row-${r.status}`} style={{ borderTop: `1px solid ${BORDER_SUBTLE}`, marginTop: 28, paddingTop: 20 }}>
                <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap", marginBottom: 12 }}>
                  <h2 id={`row-${r.status}`} style={{ margin: 0, fontSize: 22, fontWeight: 700 }}>{r.title}</h2>
                  <span style={{ color: SUBTLE }}>{STATUS_TEXT[r.status]}</span>
                </div>
                {r.items.length ? (
                  <ul style={{ margin: 0, padding: "0 0 10px", display: "grid", gridAutoFlow: "column", gridAutoColumns: 264, gap: 16, overflowX: "auto" }}>
                    {r.items.map((f) => <Card key={f.id} f={f} />)}
                  </ul>
                ) : <p style={{ color: SUBTLE, margin: 0 }}>{query ? "No match here." : "Nothing here right now."}</p>}
              </section>
            ))}
            <p style={{ color: SUBTLE, fontSize: 13, marginTop: 24 }}>Updated {data.updated}.</p>
          </>
        )}
      </main>
      <SiteFooter />
    </div>
  );
}
